import {createApp,h} from 'vue';import ElementPlus from 'element-plus';import zhCn from 'element-plus/es/locale/lang/zh-cn';import 'element-plus/dist/index.css';import '/frontend/admin/styles/index.css';import '/frontend/admin/styles/erp-theme.css';import {createRouter,createWebHashHistory,RouterView} from 'vue-router';import {createPinia} from 'pinia';import View from '/frontend/admin/views/analytics/SkuTrafficMonitorView.vue';import Analysis from '/frontend/admin/views/analytics/SellerAnalyticsView.vue';const router=createRouter({history:createWebHashHistory(),routes:[{path:'/sku-traffic-monitor',name:'sku-traffic-monitor',component:View},{path:'/seller-analytics',name:'seller-analytics',component:Analysis}]});const app=createApp({render:()=>h(RouterView)});app.use(router);app.use(createPinia());app.use(ElementPlus,{locale:zhCn});window.skuTrafficErrors=[];app.config.errorHandler=e=>window.skuTrafficErrors.push(e.message);app.mount('#adminApp');